import os
import msal
from flask import Flask, request, redirect, session, jsonify
import requests

app = Flask(__name__)
app.secret_key = os.environ.get("FLASK_SECRET_KEY", "dev-secret-change-me")

AZURE_CLIENT_ID = os.environ.get("AZURE_CLIENT_ID")
AZURE_TENANT_ID = os.environ.get("AZURE_TENANT_ID", "common")
AUTHORITY = f"https://login.microsoftonline.com/{AZURE_TENANT_ID}"
REDIRECT_URI = os.environ.get("REDIRECT_URI", "http://localhost:5000/callback")
SCOPES = ["openid", "profile", "email"]

# MSAL PublicClientApplication automatically enforces RFC 7636 PKCE (S256)
# for authorization code flows on public clients.
msal_client = msal.PublicClientApplication(
    client_id=AZURE_CLIENT_ID,
    authority=AUTHORITY
)

@app.route("/login")
def login():
    """Initiates the PKCE authorization code flow."""
    flow = msal_client.initiate_auth_code_flow(
        scopes=SCOPES,
        redirect_uri=REDIRECT_URI
    )
    session["flow"] = flow
    return redirect(flow["auth_uri"])

@app.route("/callback")
def callback():
    """Exchanges the authorization code for tokens and fetches user info."""
    flow = session.pop("flow", {})
    if not flow:
        return jsonify({"error": "No active login flow found in session."}), 400

    try:
        token_response = msal_client.acquire_token_by_auth_code_flow(
            auth_code_flow=flow,
            auth_response=dict(request.args)
        )
    except Exception as e:
        return jsonify({"error": "Token exchange failed", "details": str(e)}), 400

    if "access_token" not in token_response:
        return jsonify({
            "error": token_response.get("error"),
            "error_description": token_response.get("error_description")
        }), 401

    # Fetch user profile using the Microsoft Graph OIDC userinfo endpoint
    try:
        user_info = requests.get(
            "https://graph.microsoft.com/oidc/userinfo",
            headers={"Authorization": f"Bearer {token_response['access_token']}"}
        )
        user_info.raise_for_status()
        return jsonify(user_info.json())
    except requests.exceptions.RequestException as e:
        return jsonify({"error": "Failed to fetch user info", "details": str(e)}), 502

if __name__ == "__main__":
    app.run(host="127.0.0.1", port=5000, debug=True)
